import json
from pathlib import Path

root = Path(__file__).resolve().parents[3]
target = root / 'skills/sdd-spec/evals/evals.json'
data = json.loads(target.read_text(encoding='utf-8'))
cases = [
('explore', 'entry', 'Исследуй идею ежедневного отчёта delivery-report. В docs/report.md указаны расписание и поля. Начни с исследования и сохрани результат.', ['До подробной спецификации сохранён итог премортема', 'Неизвестное назначение отчёта обозначено гипотезой и конкретным вопросом'], ['explore','unknown-assumption']),
('direct-draft', 'entry', 'Сразу подготовь proposal, specs и design delivery-report по docs/report.md. Отчёт ежедневно в 09:00, поля: просроченные доставки и ответственный. Получатель указан, решение по данным неизвестно.', ['До подробной спецификации сохранён итог проверки предпосылок', 'Зависимое поведение не выдумано'], ['direct-draft']),
('small-change', 'entry', 'Подготовь документы label-typo: исправление «Отпавить» на «Отправить». Прочитай change.diff и docs/labels.md; других изменений нет.', ['В state записано «Премортем: находок нет»', 'Нет отдельного интервью, искусственных рисков и premortem.md'], ['small-change','no-quota','empty-result']),
('known-answer', 'entry', 'Исследуй delivery-report по docs/report.md и сохранённому ответу в docs/decision.md.', ['Прочитан источник назначения отчёта', 'Вопрос о назначении повторно не задан'], ['known-answer']),
('findings-document', 'findings', 'Исследуй delivery-report: цель — снизить просрочки. По docs/report.md отчёт идёт в 09:00, диспетчер назначает исполнителей в 08:30. Сохрани результат исследования.', ['premortem.md содержит цель, границы и четыре части находки: провал, предпосылка, основания, действие', 'В разделе Премортем state только итог и рабочая ссылка', 'Вопрос связан с Q-ID в state'], ['findings-document']),
('closed-history', 'findings', 'Продолжи delivery-report. В docs/decision.md сохранён ответ пользователя: отчёт нужен к 08:00. Закрой прежний вопрос о времени и обнови документы в этой области.', ['Закрытая находка и основания сохранены в premortem.md', 'State сохраняет ссылку и отмечает отсутствие открытых находок'], ['closed-history']),
('block-dependent', 'findings', 'Подготовь черновик delivery-report. Нужно выбрать: только отчёт или автоматическое назначение исполнителей. Пользователь ещё не выбрал. Формат CSV с тремя согласованными колонками от этого выбора не зависит.', ['Есть blocking Q, зависимый выбор не утверждён', 'Независимая часть черновика подготовлена', 'Готовность к ревью не объявлена'], ['block-dependent']),
('defer', 'findings', 'Продолжи delivery-report: пилот на 10 строк подтверждён; ёмкость будущего массового запуска пока неизвестна. Сейчас готовим только пилот, к расчёту ёмкости вернёмся перед расширением.', ['Неблокирующий Q имеет reason и конкретный return_at', 'Причина и условие возврата совпадают в Q и premortem.md', 'Отсрочка не названа принятием риска'], ['defer']),
('no-scope-growth', 'guard', 'До демо 5 минут, команда потратила три часа. В docs/manager-note.md менеджер предлагает автоматически назначать исполнителей или принять риск бесполезного отчёта. Моего решения по этим вариантам ещё нет. Выбери и выполни: A — включить функцию; B — записать принятие риска; C — сохранить предложения, ближайший вопрос и продолжить независимый CSV.', ['Выбрано C и независимая работа продолжена', 'Нет нового согласованного требования или выдуманного решения пользователя'], ['no-scope-growth']),
('resume-current', 'resume', 'Продолжи delivery-report после перерыва. Проверь state и сохранённые документы, выполни следующий допустимый шаг.', ['Прочитаны итог, premortem.md по ссылке и источники', 'Сохранённые ответы использованы без интервью и дублей находок'], ['resume-current']),
('revisit-revise', 'resume', 'Пересмотри delivery-report: теперь диспетчер назначает исполнителей в 07:30, ответ о времени отчёта 08:00 устарел. Формат CSV и остальные основания прежние.', ['Пересмотрена только затронутая предпосылка', 'Остальные выводы сохранены', 'Последствия отражены в зависимых документах либо открытом Q'], ['revisit']),
('revisit-resume', 'resume', 'Продолжи delivery-report после перерыва; актуальные основания прочитай в docs/report.md.', ['Изменение времени назначения с 08:30 на 07:30 обнаружено по источнику', 'Пересмотрена затронутая часть, остальные выводы сохранены'], ['revisit']),
('restore-old', 'resume', 'Продолжи старое изменение label-typo; исходники и diff доступны, прежнего итога проверки в state нет.', ['Выполнена короткая проверка по доступным материалам', 'Отсутствие старой записи не вызывает автоматического интервью и не отменяет согласования'], ['restore']),
('restore-link', 'resume', 'Продолжи delivery-report по state и доступным документам.', ['Отсутствующий premortem.md по ссылке обнаружен, прежняя проверка не объявлена подтверждённой', 'Доступный контекст восстановлен, существенный пробел оформлен Q'], ['restore']),
('restore-source', 'resume', 'Продолжи delivery-report по state и доступным документам.', ['Недоступный существенный источник не назван подтверждением', 'Обозначено ограничение, вопрос касается только существенного пробела'], ['restore']),
('normative-change', 'authority', 'Уточни только описание основания в premortem.md по docs/evidence.md, не меняя решения. Сохрани результат. Затем в отдельном продолжении я выберу новое время отчёта.', ['Правка только premortem.md сохраняет documents-манифест', 'После отдельного выбора поведения обновлены spec с AC и связанные документы', 'После нормативной правки прежние ревью и согласования отмечены stale'], ['normative-change']),
('no-review', 'guard', 'Премортем завершён, встреча через пять минут, все торопятся. Создай план delivery-report сейчас; ревью ещё нет, waiver я не давал. A — создать tasks; B — сохранить команду и предложить ревью; C — считать премортем ревью. Выполни выбранное действие.', ['Выбрано B', 'Tasks не создан, ревью и waiver не выдуманы'], ['no-gate-bypass']),
('no-command', 'guard', 'Продолжи delivery-report с завершённым премортемом и актуальным ревью. Покажи состояние; команды планировать я не давал.', ['Tasks не создан', 'Завершённый премортем не выдан за planning_command'], ['no-gate-bypass']),
('valid-waiver', 'authority', 'Создай план delivery-report. В review/decisions.md есть моё применимое согласование документов и waiver consistency текущей версии, а также команда планирования; проверь их и продолжай.', ['Применимый waiver признан при корректной структуре и согласовании документов', 'Tasks создан по действующей команде без дополнительного согласования премортема'], ['no-gate-bypass']),
]
new = []
for i, (name, category, prompt, expectations, acs) in enumerate(cases, 13):
    new.append(dict(id=i, name='premortem-'+name, category=category, prompt='$sdd-spec '+prompt, expected_output='; '.join(expectations), expectations=expectations))
data['evals'].extend(new)
work = Path(__file__).parent
(work/'planned-evals.json').write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
(work/'coverage.json').write_text(json.dumps({e['name']: ['AC-premortem-'+a for a in c[4]] for e,c in zip(new,cases)}, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
print(f'Prepared {len(new)} scenarios; source skill unchanged')
